using System;using System.IO;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace ServiceTool{static class OpeningProgressTests{
[STAThread]static int Main(){try{using(var form=new SoftwareManagerForm(true,id=>null)){var flags=BindingFlags.Instance|BindingFlags.NonPublic;var type=typeof(SoftwareManagerForm);string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"opening-empty-soft");Directory.CreateDirectory(root);type.GetField("preview",flags).SetValue(form,false);type.GetField("source",flags).SetValue(form,root);var handle=form.Handle;var task=(Task)type.GetMethod("RefreshPackages",flags).Invoke(form,new object[]{false});var view=(DownloadProgressView)type.GetField("transfer",flags).GetValue(form);if(view.Snapshot.Active)throw new Exception("Opening scan starts animation");var end=DateTime.UtcNow.AddSeconds(30);while(!task.IsCompleted&&DateTime.UtcNow<end){Application.DoEvents();Thread.Sleep(5);}if(!task.IsCompleted)throw new Exception("Opening scan timeout");task.GetAwaiter().GetResult();if(view.Snapshot.Active||view.Snapshot.Complete)throw new Exception("Opening scan leaves active/success progress");Console.WriteLine("PASS: actual local software scan starts/stays idle and finishes without animation or 100%. "+view.Snapshot.Stage);}return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}}